183	// Impact names one dataset directly or indirectly downstream of an impact
184	// query's origin. Distance is the number of lineage edges on the shortest path
185	// from the origin to this dataset (a direct downstream has distance 1), and
186	// Path is that shortest path written from the origin to the dataset, one name
187	// per hop.
188	type Impact struct {
189		Dataset  string
190		Distance int
191		Path     []string
192	}
193	
194	// Impacts returns every dataset directly or indirectly downstream of origin,
195	// i.e. every dataset reachable from origin by following child edges. The origin
196	// itself is never listed, and datasets with no such connection never appear.
197	//
198	// Distance is the shortest edge count; each dataset is returned at most once
199	// even where several branches merge into it. When several shortest paths exist,
200	// the lexicographically smallest full path (name by name, Go string order) is
201	// reported. Results are ordered by distance and then by dataset name, never by
202	// registration order or the stored parent/child list order.
203	//
204	// The graph is read only: a successful or failed query changes no node, edge or
205	// ordering. The returned Path slices are independent copies, so mutating them
206	// cannot affect the graph. An empty origin is rejected as a missing name; an
207	// origin absent from the graph (including an empty or nil graph) is rejected
208	// with an error naming it and no partial results.
209	func Impacts(graph map[string]*Lineage, origin string) ([]Impact, error) {
210		if origin == "" {
211			return nil, errInvalid("dataset name is required")
212		}
213		if _, ok := graph[origin]; !ok {
214			return nil, errInvalid("dataset not found: " + origin)
215		}
216	
217		// BFS one distance level at a time. A node commits its distance and best
218		// (lexicographically smallest) shortest path only once the whole level is
219		// known, so candidates reaching the same child through different parents in
220		// the same level can be compared before either wins. Register rejects
221		// cycles, so a committed node is never reached again at an equal level.
222		distance := map[string]int{origin: 0}
223		best := map[string][]string{origin: {origin}}
224		frontier := []string{origin}
225		for d := 0; len(frontier) > 0; d++ {
226			nextDistance := d + 1
227			candidates := map[string][]string{}
228			var next []string
229			for _, node := range frontier {
230				for _, child := range graph[node].Children {
231					if _, seen := distance[child]; seen {
232						continue // reached on an earlier, strictly shorter level
233					}
234					// Fresh backing array per candidate: paths must not alias each
235					// other or any slice stored in the graph.
236					candidate := make([]string, len(best[node])+1)
237					copy(candidate, best[node])
238					candidate[len(candidate)-1] = child
239					if current, ok := candidates[child]; !ok || lessPath(candidate, current) {
240						if !ok {
241							next = append(next, child)
242						}
243						candidates[child] = candidate
244					}
245				}
246			}
247			for _, child := range next {
248				distance[child] = nextDistance
249				best[child] = candidates[child]
250			}
251			frontier = next
252		}
253	
254		impacts := make([]Impact, 0, len(distance)-1)
255		for name, d := range distance {
256			if name == origin {
257				continue
258			}
259			impacts = append(impacts, Impact{
260				Dataset:  name,
261				Distance: d,
262				Path:     append([]string(nil), best[name]...),
263			})
264		}
265		sort.Slice(impacts, func(i, j int) bool {
266			if impacts[i].Distance != impacts[j].Distance {
267				return impacts[i].Distance < impacts[j].Distance
268			}
269			return impacts[i].Dataset < impacts[j].Dataset
270		})
271		return impacts, nil
272	}
273	
274	// Upstream names one dataset directly or indirectly upstream of a provenance
275	// query's target. Distance is the number of lineage edges on the shortest path
276	// from this upstream to the target (a direct upstream has distance 1), and
277	// Path is that shortest path written along the actual derivation direction,
278	// from this upstream to the queried dataset, one name per hop.
279	type Upstream struct {
280		Dataset  string
281		Distance int
282		Path     []string
283	}
284	
285	// Upstreams returns every dataset directly or indirectly upstream of target,
286	// i.e. every dataset reachable from target by following parent edges. The
287	// target itself is never listed, its downstreams never appear, and datasets
288	// with no such connection never appear.
289	//
290	// Distance is the shortest edge count; each upstream is returned at most once
291	// even where it feeds the target through several branches. When several
292	// shortest paths exist, the lexicographically smallest full path (name by
293	// name from the upstream onward, Go string order) is reported. Results are
294	// ordered by distance and then by upstream name, never by registration order
295	// or the stored parent/child list order.
296	//
297	// The graph is read only: a successful or failed query changes no node, edge
298	// or ordering. The returned Path slices are independent copies, so mutating
299	// them cannot affect the graph, other records, or later queries. An empty
300	// target is rejected as a missing name; a target absent from the graph
301	// (including an empty or nil graph) is rejected with an error naming it and
302	// no partial results.
303	func Upstreams(graph map[string]*Lineage, target string) ([]Upstream, error) {
304		if target == "" {
305			return nil, errInvalid("dataset name is required")
306		}
307		if _, ok := graph[target]; !ok {
308			return nil, errInvalid("dataset not found: " + target)
309		}
310	
311		// BFS one distance level at a time along parent edges, mirroring Impacts.
312		// A node commits its distance and best (lexicographically smallest)
313		// shortest path only once the whole level is known, so candidates reaching
314		// the same upstream through different children in the same level can be
315		// compared before either wins. Paths are stored from the upstream toward
316		// the target, so a candidate prepends the parent to the child's committed
317		// path; candidates for one parent share its name as the first hop, which
318		// makes the committed per-child paths directly comparable.
319		distance := map[string]int{target: 0}
320		best := map[string][]string{target: {target}}
321		frontier := []string{target}
322		for d := 0; len(frontier) > 0; d++ {
323			nextDistance := d + 1
324			candidates := map[string][]string{}
325			var next []string
326			for _, node := range frontier {
327				for _, parent := range graph[node].Parents {
328					if _, seen := distance[parent]; seen {
329						continue // reached on an earlier, strictly shorter level
330					}
331					// Fresh backing array per candidate: paths must not alias each
332					// other or any slice stored in the graph.
333					candidate := make([]string, len(best[node])+1)
334					candidate[0] = parent
335					copy(candidate[1:], best[node])
336					if current, ok := candidates[parent]; !ok || lessPath(candidate, current) {
337						if !ok {
338							next = append(next, parent)
339						}
340						candidates[parent] = candidate
341					}
342				}
343			}
344			for _, parent := range next {
345				distance[parent] = nextDistance
346				best[parent] = candidates[parent]
347			}
348			frontier = next
349		}
350	
351		upstreams := make([]Upstream, 0, len(distance)-1)
352		for name, d := range distance {
353			if name == target {
354				continue
355			}
356			upstreams = append(upstreams, Upstream{
357				Dataset:  name,
358				Distance: d,
359				Path:     append([]string(nil), best[name]...),
360			})
361		}
362		sort.Slice(upstreams, func(i, j int) bool {
363			if upstreams[i].Distance != upstreams[j].Distance {
364				return upstreams[i].Distance < upstreams[j].Distance
365			}
366			return upstreams[i].Dataset < upstreams[j].Dataset
367		})
368		return upstreams, nil
369	}
370	
371	// lessPath reports whether path a sorts before path b as a name sequence:
372	// names are compared with Go string order from the start, and an equal prefix
373	// makes the shorter path smaller.
374	func lessPath(a, b []string) bool {
375		for i := 0; i < len(a) && i < len(b); i++ {
376			if a[i] != b[i] {
377				return a[i] < b[i]
378			}
379		}
380		return len(a) < len(b)
381	}
382	
383	// Roots lists datasets with no parents, in stable order.
384	func Roots(graph map[string]*Lineage) []string {
385		var roots []string
386		for name, entry := range graph {
387			if len(entry.Parents) == 0 {
388				roots = append(roots, name)
389			}
390		}
391		sort.Strings(roots)
392		return roots
393	}
394	
395	type errInvalid string
396	
397	func (e errInvalid) Error() string { return string(e) }
